<?php

namespace App\Models;

use App\Exceptions\PhysicalDeleteNotAllowed;
use Database\Factories\FinancialEntryFactory;
use Illuminate\Database\Eloquent\Factories\HasFactory;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Relations\BelongsTo;
use Illuminate\Database\Eloquent\SoftDeletes;
use Illuminate\Support\Carbon;
use Spatie\Activitylog\Models\Concerns\LogsActivity;
use Spatie\Activitylog\Support\LogOptions;

/**
 * Income or expense of the cash book; automatic when generated by a payment.
 *
 * @property int $id
 * @property int $entry_type_id
 * @property int $financial_category_id
 * @property string $description
 * @property string $amount
 * @property Carbon $due_date
 * @property int $entry_status_id
 * @property Carbon|null $paid_at
 * @property int|null $payment_method_id
 * @property int|null $payment_id
 * @property string|null $supplier_or_payer
 * @property string|null $notes
 * @property int $user_id
 * @property Carbon|null $created_at
 * @property Carbon|null $updated_at
 * @property Carbon|null $deleted_at
 */
class FinancialEntry extends Model
{
    /** @use HasFactory<FinancialEntryFactory> */
    use HasFactory, LogsActivity, SoftDeletes;

    /**
     * The attributes that are mass assignable.
     *
     * @var list<string>
     */
    protected $fillable = [
        'entry_type_id',
        'financial_category_id',
        'description',
        'amount',
        'due_date',
        'entry_status_id',
        'paid_at',
        'payment_method_id',
        'payment_id',
        'supplier_or_payer',
        'notes',
        'user_id',
    ];

    /**
     * Entries are only soft deleted (manual ones) or cancelled, never removed.
     */
    protected static function booted(): void
    {
        static::forceDeleting(function (self $entry): never {
            throw PhysicalDeleteNotAllowed::for($entry);
        });
    }

    /**
     * Audit changes to the fillable attributes in the "finance" log; the causer
     * is the authenticated user (none when run by the scheduled routines).
     */
    public function getActivitylogOptions(): LogOptions
    {
        return LogOptions::defaults()
            ->useLogName('finance')
            ->logFillable()
            ->logOnlyDirty()
            ->dontLogEmptyChanges();
    }

    /**
     * Get the attributes that should be cast.
     *
     * @return array<string, string>
     */
    protected function casts(): array
    {
        return [
            'amount' => 'decimal:2',
            'due_date' => 'date',
            'paid_at' => 'date',
        ];
    }

    /**
     * @return BelongsTo<EntryType, $this>
     */
    public function type(): BelongsTo
    {
        return $this->belongsTo(EntryType::class, 'entry_type_id');
    }

    /**
     * @return BelongsTo<FinancialCategory, $this>
     */
    public function category(): BelongsTo
    {
        return $this->belongsTo(FinancialCategory::class, 'financial_category_id');
    }

    /**
     * @return BelongsTo<EntryStatus, $this>
     */
    public function status(): BelongsTo
    {
        return $this->belongsTo(EntryStatus::class, 'entry_status_id');
    }

    /**
     * @return BelongsTo<PaymentMethod, $this>
     */
    public function method(): BelongsTo
    {
        return $this->belongsTo(PaymentMethod::class, 'payment_method_id');
    }

    /**
     * Payment that generated the entry, when automatic.
     *
     * @return BelongsTo<Payment, $this>
     */
    public function payment(): BelongsTo
    {
        return $this->belongsTo(Payment::class);
    }

    /**
     * User who registered the entry.
     *
     * @return BelongsTo<User, $this>
     */
    public function user(): BelongsTo
    {
        return $this->belongsTo(User::class);
    }

    /**
     * Whether the entry was generated by a payment instead of typed by a user.
     */
    public function isAutomatic(): bool
    {
        return $this->payment_id !== null;
    }
}
